from scipy.optimize import minimize
t,x,v,a=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
mults={'1':np.ones_like(x),'x':x,'v':v,'x1.5':x**1.5,'v2':v*v,'x2':x*x,'xv':x*v,'sinx':np.sin(x),'expv':np.exp(-v),'expx':np.exp(-x),'1/x':1/x,'sqv':np.sqrt(v),'v1.5':v**1.5}
def L(p,m,fam):
    c3,k=p
    if c3<=-1/x.max(): return 1e9
    g={'cos':np.cos(k*t),'sin':np.sin(k*t)}[fam]*m
    F=np.c_[x**1.5, x/(1+c3*x)*v, t*np.log(t)*x**1.5, g]
    coef=np.linalg.lstsq(F,a,rcond=None)[0]
    return np.mean((a-F@coef)**2)/np.var(a)
res=[]
