  for fam in ['cos','sin']:
    best=None
    for k0 in [0.4,0.54,0.7]:
        r=minimize(L,[1.0,k0],args=(m,fam),method='Nelder-Mead',options={'xatol':1e-9,'fatol':1e-13,'maxiter':3000})
        if best is None or r.fun<best.fun: best=r
    res.append((best.fun,mn,fam,best.x.round(5)))
